('8811e72c-1f02-4777-a4e3-d4d1b4d73fe6', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "922960ab-61ee-4067-8769-791fbe5c0380", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "75416124-f1e9-48c1-b028-d7bbc5bb0e59", "text": "3/5", "isCorrect": true}, {"id": "49689787-e54d-414a-ae8c-614e95c9f8aa", "text": "12/20", "isCorrect": false}, {"id": "a33fcc14-368a-4ffd-a650-7da62bf28b75", "text": "7/9", "isCorrect": false}, {"id": "2c49ce40-30d6-40b4-9e7a-2904400c8413", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3b554322-6be8-4a81-a329-f89ba3190dc0", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "37c90f0f-73d3-4920-b38b-d6688a2c0c41", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "a217e29f-05e8-4e28-98eb-cd04cfa72529", "text": "1/6", "isCorrect": false}, {"id": "2475d3f1-1aa2-4909-9778-64eeadec630b", "text": "2/3", "isCorrect": false}, {"id": "6abdf120-adef-4ab7-8f71-3c9e0c959050", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "635cf532-f544-48e9-9eff-557bd4945aa0", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "e9f619e9-4798-4ce4-9793-12762ef33888", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "844212f7-02b9-4ea2-9c9b-87e37effe3f0", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "db471437-496b-4499-abee-5e968bf2c4b8", "text": "Igaz", "isCorrect": true}, {"id": "bf9e5f9d-4345-4524-ae04-956927a2033c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3d888f56-fa79-4233-99a0-430c06a6388f", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f6f60b4