('dccf1eba-7989-4ea2-a93a-1adbc606b697', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "32387511-1885-4249-988e-3714ef3ef401", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "93f12d17-d283-44ed-ac45-c07e34636955", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "ef0f3b45-cded-44a6-9382-4ed55c8f313f", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "8a91d042-5371-4747-ac7f-723c176211db", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "be5535bb-3e31-4f59-8119-2df2db5a5c38", "text": "1/5", "isCorrect": false}, {"id": "ef1cd59d-4e1a-4277-a8da-e1095aed1011", "text": "1/2", "isCorrect": false}, {"id": "fa0d09af-d018-40c2-9900-73f8ac24630a", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "00fac468-cb89-4bd6-9854-7f06326c2e8d", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "e1893b3c-587a-4746-9be8-85bf27bf2dae", "text": "Igaz", "isCorrect": true}, {"id": "79d42ad2-4156-4d13-8e66-fe0ee4fa7c0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99a26a85-52e3-4aa7-9ef9-57ce8f0342b8", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "22ae93b4-3d73-4f09-ada6-66f6a9aa15cc", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "df9ab6e9-4a4e-4701-8464-d5056cae4f6a", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "cbae0ff9-c637-4d2f-8489-6640720ad5f6", "text": "Igaz", "isCorrect": true}, {"id": "0a654229-be53-4f71-ba02-ab023211ddd3", "te