('6aa21684-11da-49b7-9f4b-4d2147553efc', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "57d06629-7b74-4125-8d98-b76dbe2d31c8", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "cb326637-8487-4dd1-9d8d-3df84261d918", "text": "1/3", "isCorrect": true}, {"id": "1b86a5b5-cab6-4973-9f07-071e1581b594", "text": "1/4", "isCorrect": false}, {"id": "479b90dc-511e-415c-a5ca-e1141aabda8f", "text": "2/3", "isCorrect": false}, {"id": "7123c078-843e-4890-9e83-0c34600172d2", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7d6fc33f-cfb3-47a8-8541-8f772daaa76d", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "9cfef646-d9bb-4844-89d5-bcf7bea8e892", "text": "1/4", "isCorrect": true}, {"id": "63ef3518-731b-4b42-bcc7-d03655325d8a", "text": "1/5", "isCorrect": false}, {"id": "f417ec6a-7014-488c-a68c-cb469f7e2a76", "text": "2/5", "isCorrect": false}, {"id": "7e25fce5-dbd6-473c-ae23-e41fd5f8d489", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c771ed2d-78fa-4b07-9c44-452473184948", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "65d37756-f4e9-4203-8583-daed9e575113", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "dbdad7e8-a124-48ba-a183-772d240ba7f7", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "71aae914-1555-4323-a33c-0eed3d88679b", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "a3b2487b-f7a9-4a97-a8eb-3361b0ddf95c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56749c11-4db9-430a-804d-17238abec987", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "061