('9813f2de-ac3f-494b-ae9b-3f65e3d676cc', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "55553fd3-363d-459e-ae56-593c3bd705fd", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "5c68e43f-963b-49f8-b519-1735905531c4", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "5b0e5392-04be-40d8-9a34-f85d6b1c33d9", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "94f56ffe-2365-4454-be47-13b1c4f35ca3", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "90bcc1e7-643d-445d-8b19-73732b6a9be6", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "bdd10ddb-4a46-4003-9b5d-1e0ff5797eba", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "b94fe913-f10b-4f3d-adf4-f018c007146b", "text": "Igaz", "isCorrect": false}, {"id": "d6bedf82-0f7b-4cb6-b5d7-ce6e03e77e0c", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "99d111ba-d2f7-4f3e-b3ad-b98c93c8d6aa", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "27282e93-2908-47c1-9961-798e6b9e8546", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "220c35c0-e026-4123-aef6-16719c3f8b37", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15d256cc-ef1a-4963-8cff-4a5eda306994", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "0be6210e-bdb0-4bb0-8f3d-1eceab6c602e", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkeszté