('5408f11f-904b-45ac-973e-1d4eb5caeb9c', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "54b32f1f-8978-4973-a3de-dc50d3fb7d59", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "071e13eb-2bcf-4735-9024-3a2ff02ba2e5", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "3802489c-7764-4268-bf14-10e7246d389f", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "c282490f-8270-4f28-8163-8a8b3d40f5f5", "text": "Igaz", "isCorrect": false}, {"id": "7b6a73b6-25ab-4f98-9dc0-3d6aadfea667", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "f2efa199-dcaf-4e7e-b48f-640817961bef", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "f8aae2c3-a72e-4d5f-be08-92cc25cb7f9a", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "69f82b64-8f62-420c-9382-bf86d05a3429", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "68622961-d9eb-41f3-94a5-0e1ef67fad09", "text": "Igaz", "isCorrect": true}, {"id": "f6470a48-cdf0-4815-bfd7-4f6104fffe55", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26dc86e2-a7e5-4bdf-8332-55205012ae3a", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "97ac6dea-0446-46c5-b970-dce933eeec10", "text": "Tompaszög", "isCorrect": true}, {"id": "3bba0025-3185-4774-93c1-42c2397f8543", "text": "Hegyesszög", "isCorrect": false}, {"id": "9a32a95f-36