('e747a24c-30f5-48f8-a104-4b09e9c4675f', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6d05a47c-7424-4037-bd4d-c86cf9d55ea1", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "f275e5d2-670a-4851-b889-b9070196f723", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "d85e2220-cc67-4d0c-83dc-04597dd19836", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "a9542710-0008-40f0-9902-93f9a0cece5c", "text": "7 négyzet", "isCorrect": false}, {"id": "8f642942-86f5-4c41-badf-5856540924cb", "text": "7 kör", "isCorrect": false}, {"id": "15054346-7a95-4181-b382-46cbdfaad1e9", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "33db275d-9f0d-430d-b2b7-ab450464461e", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "0c374df3-d5d2-40ae-9039-bd5d2a03c569", "text": "Igaz", "isCorrect": true}, {"id": "cdce05b6-e49e-4b90-b561-e3bb56f67ebb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dffbadc1-302f-41a6-b615-fec5abfba047", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "78d64597-cacc-472c-9b50-bc87225a97c6", "text": "Igaz", "isCorrect": true}, {"id": "bd2e0fa3-9cfe-4f06-8281-767bf6f8c8ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "36127e8f-798f-4d1b-82c3-984b87726268", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "197eb593-76f3-43ca-a595-651d764d71e2", "text": "Igaz", "isCorrect": true}, {"id": "0f46dbc1-34ec-4252-8